INSERT INTO prism_layers (layer_id, layer_name, raw_group, friction_category, source_url, source_layer_id, service_type, geometry_type, friction_weight, friction_tier, description) VALUES
  ('usfs_right_of_way__EDW_ALPStatusAndEncumbrance_01-71', 'USFS - Right of Way', 'Infrastructure', 'infrastructure', 'https://apps.fs.usda.gov/arcx/rest/services/EDW/EDW_ALPStatusAndEncumbrance_01/MapServer', 71, 'MapServer', 'polygon', 5, 'low', 'A map service designed to portray US Forest Service Land Status Record System data. The map service is for querying and displaying Land Status Record System information for Lands under Forest Service Management. Using this service in the US Forest Service Map Service Viewer the user will be able to view Land Status Record System layers with various supplied background imagery and layers.'),
