  ('usfws_wetlands__USA_Wetlands-0', 'USFWS Wetlands', 'Floodplains', 'floodplain_wetland', 'https://services.arcgis.com/P3ePLMYs2RVChkJx/arcgis/rest/services/USA_Wetlands/FeatureServer', 0, 'FeatureServer', 'polygon', 30, 'high', NULL),
