INSERT INTO prism_layers (layer_id, layer_name, raw_group, friction_category, source_url, source_layer_id, service_type, geometry_type, friction_weight, friction_tier, description) VALUES
  ('wildlife_management_areas__Mississippi_State_Parks_and_WMAs-1', 'Wildlife Management Areas', 'Mississippi - State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Mississippi_State_Parks_and_WMAs/FeatureServer', 1, 'FeatureServer', 'polygon', 5, 'low', 'Mississippi State Parks and Wildlife Management Areas.'),
  ('missouri_state_lands__Missouri_State_Lands-0', 'Missouri State Lands', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Missouri_State_Lands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'Missouri State Lands'),
  ('montana_public_lands__Montana_Public_Lands-0', 'Montana Public Lands', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Montana_Public_Lands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('nebraska_game_and_parks_commission_property__NPGCProperties2023_2024-268', 'Nebraska - Game and Parks Commission Property', 'State Lands', 'state_protected', 'https://services5.arcgis.com/IOshH1zLrIieqrNk/arcgis/rest/services/NPGCProperties2023_2024/FeatureServer', 268, 'FeatureServer', 'polygon', 5, 'low', 'NPGCProperties2023_2024'),
  ('new_hampshire_conservation_public_lands__Conservation-6', 'New Hampshire - Conservation/Public Lands', 'State Lands', 'state_protected', 'https://nhgeodata.unh.edu/nhgeodata/rest/services/EC/Conservation/MapServer', 6, 'MapServer', 'polygon', 5, 'low', 'The Conservation and Public Lands in New Hampshire dataset comprises conservation and public areas displayed by management status, protecting agency type, primary protection type, protection level, and gap status. This is a dynamic data set which is updated on a biannual basis. The updates are based on contributions from numerous various conservation entities located throughout New Hampshire. For more information, see http://www.granit.unh.edu/data/metadata?file=consnh/nh/consnh.html'),
  ('new_jersey_open_space_and_recreation_areas__Land-65', 'New Jersey - Open Space and Recreation Areas', 'State Lands', 'state_protected', 'https://mapsdep.nj.gov/arcgis/rest/services/Features/Land/MapServer', 65, 'MapServer', 'polygon', 5, 'low', 'NJDEP''s Land data for publication and use in public applications.'),
  ('new_mexico_state_trust_land__New_Mexico_State_Trust_Land-0', 'New Mexico - State Trust Land', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/New_Mexico_State_Trust_Land/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('adirondack_park_boundary__BluelinePolygon-0', 'Adirondack Park Boundary', 'New York', 'state_protected', 'https://services2.arcgis.com/8krRUWgifzA4cgL3/arcgis/rest/services/BluelinePolygon/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'Boundary polygon of the New York State Adirondack Park for planning purposes, not derived from licensed land survey. 2018 edition.'),
  ('adirondack_park_land_use_and_development_plan__Adirondack_Park_State_and_Private_Land_Class_Features-0', 'Adirondack Park Land Use and Development Plan', 'Adirondack Park State and Private Land Class Features', 'state_protected', 'https://services2.arcgis.com/8krRUWgifzA4cgL3/arcgis/rest/services/Adirondack_Park_State_and_Private_Land_Class_Features/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'Feature Service of State and Private Land Classification in the Adirondack Park of New York'),
  ('state_land_map__Adirondack_Park_State_and_Private_Land_Class_Features-1', 'State Land Map', 'Adirondack Park State and Private Land Class Features', 'state_protected', 'https://services2.arcgis.com/8krRUWgifzA4cgL3/arcgis/rest/services/Adirondack_Park_State_and_Private_Land_Class_Features/FeatureServer', 1, 'FeatureServer', 'polygon', 5, 'low', 'Feature Service of State and Private Land Classification in the Adirondack Park of New York'),
  ('state_parks__NYS_Park_Polygons-0', 'State Parks', 'New York', 'state_protected', 'https://services.arcgis.com/1xFZPtKn1wKC6POA/arcgis/rest/services/NYS_Park_Polygons/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'New York State Office of Parks, Recreation and Historic Preservation Property
'),
  ('state_owned_parcels__NYS_Tax_Parcels_State_Owned-0', 'State Owned Parcels', 'New York', 'state_protected', 'https://gisservices.its.ny.gov/arcgis/rest/services/NYS_Tax_Parcels_State_Owned/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'Publication Date: April 2025. Updated annually. This map service only contains parcel data for NYS State-owned tax parcels. 2024 Parcel geometry was incorporated as received from County Real Property Departments. No attempt was made to edge-match parcels along adjacent counties. County attribute values were populated using 2024 Assessment Roll tabular data NYS ITS Geospatial Services obtained from the NYS Department of Tax and Finance’s Office of Real Property Tax Services (ORPTS). Attribute values are from the 2024 Assessment roll year. Tabular assessment data was joined to the county provided parcel geometry using the SWIS & SBL or SWIS & PRINT KEY unique identifier for each parcel. Detailed information about assessment attributes can be found in the ORPTS Assessor’s Manuals available here: https://www.tax.ny.gov/research/property/assess/manuals/assersmanual.htm. New York City data comes from NYC MapPluto which can be found here: https://www1.nyc.gov/site/planning/data-maps/open-data/dwn-pluto-mappluto.page. The State-owned tax parcel polygons in this file are the result of a best effort selection based on the Primary Owner and Additional Owner fields in the NYS Statewide Tax Parcels file, Geospatial Services data, State agency data, and online research. These same data and information are also the basis for a best effort assignment of a NYS agency name (listed in the NYS Name field) to most tax parcel polygons where the Owner Type field value is State. The NYS Name Source field consists of a code that describes how the State-owned designation and agency name were determined, if this was verified, and the means of verification, if applicable. Geometry accuracy varies by contributing county. This map service is available to the public. The State of New York, acting through the New York State Office of Information Technology Services, makes no representations or warranties, express or implied, with respect to the use of or reliance on the Data provided. The User accepts the Data provided “as is” with no guarantees that it is error free, complete, accurate, current or fit for any particular purpose and assumes all risks associated with its use. The State disclaims any responsibility or legal liability to Users for damages of any kind, relating to the providing of the Data or the use of it. Users should be aware that temporal changes may have occurred since this Data was created.'),
  ('north_carolina_state_owned_lands__State_Owned_Land_NC_Latest_02-0', 'North Carolina -  State Owned Lands', 'State Lands', 'state_protected', 'https://services3.arcgis.com/zMTrRjxZirPAKsKd/arcgis/rest/services/State_Owned_Land_NC_Latest_02/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('state_parks__NDGISHUB_State_Parks-0', 'State Parks', 'North Dakota', 'state_protected', 'https://services1.arcgis.com/GOcSXpzwBHyk2nog/arcgis/rest/services/NDGISHUB_State_Parks/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'The purpose of this data layer is to provide a geographic representation of the state parks.  Other properties owned and/or managed by the ND Parks and Recreation Department are included in this layer.  This dataset is primarily used as a framework layer for use in GIS and other mapping applications and does not represent a land survey of the boundaries.'),
  ('state_forest__NDGISHUB_State_Forest-0', 'State Forest', 'North Dakota', 'state_protected', 'https://services1.arcgis.com/GOcSXpzwBHyk2nog/arcgis/rest/services/NDGISHUB_State_Forest/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'The purpose of the data is to provide a geographic representation of state forest lands in North Dakota. This dataset is primarily used as a framework data layer for use in GIS and mapping applications.'),
  ('ohio_dnr_lands__ODNR_ODNR_Lands_External-0', 'Ohio - DNR Lands', 'State Lands', 'state_protected', 'https://gis.ohiodnr.gov/arcgis/rest/services/OIT_Services/ODNR_ODNR_Lands_External/MapServer', 0, 'MapServer', 'polygon', 5, 'low', 'The ODNR_LANDS feature class is a generalized digital representation of the Ohio Department of Natural Resources land facilities, and contains property type and ownership classifications.
'),
  ('oregon_state_parks__Oregon_State_Parks-0', 'Oregon State Parks', 'Oregon', 'state_protected', 'https://maps.prd.state.or.us/arcgis/rest/services/Land_ownership/Oregon_State_Parks/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'Approximate real property boundaries for lands owned or managed by OPRD'),
  ('dept_of_forestry_managed_lands__Ownership_ManagedLands-0', 'Dept. of Forestry Managed Lands', 'Oregon', 'state_protected', 'https://services8.arcgis.com/8PAo5HGmvRMlF2eU/arcgis/rest/services/Ownership_ManagedLands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'Board of Forestry lands and Common School Lands Managed by the State Forests Program of the Oregon Department of Forestry.
To display ODF managed lands on maps and other graphics, and to conduct analysis involving ownership attributes.'),
  ('puerto_rico_conservation_areas__Puerto_Rico_Conservation_Areas-0', 'Puerto Rico - Conservation Areas', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Puerto_Rico_Conservation_Areas/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('rhode_island_state_conservation_lands__ENV_Conservation_Lands_State_spf-0', 'Rhode Island - State Conservation Lands', 'State Lands', 'state_protected', 'https://services2.arcgis.com/S8zZg9pg23JUEexQ/arcgis/rest/services/ENV_Conservation_Lands_State_spf/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'General reference for planning purposes and small scale cartographic output.'),
  ('south_carolina_dnr_public_properties__SCDNR_Public_Lands_Temp_App_View-4', 'South Carolina - DNR Public Properties', 'State Lands', 'state_protected', 'https://services.arcgis.com/acgZYxoN5Oj8pDLa/arcgis/rest/services/SCDNR_Public_Lands_Temp_App_View/FeatureServer', 4, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('tennessee_public_access_lands__TDEC_Public_Access_Lands-0', 'Tennessee - Public Access Lands', 'State Lands', 'state_protected', 'https://services5.arcgis.com/bPacKTm9cauMXVfn/arcgis/rest/services/TDEC_Public_Access_Lands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('texas_state_agency_lands__Texas_State_Agency_Lands-0', 'Texas State Agency Lands', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Texas_State_Agency_Lands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('utah_land_ownership__Utah_Land_Ownership-0', 'Utah Land Ownership', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Utah_Land_Ownership/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('vermont_agency_of_natural_resources_land__OPENDATA_ANR_CADASTRAL_SP_NOCACHE_v2-38', 'Vermont - Agency of Natural Resources Land', 'State Lands', 'state_protected', 'https://anrmaps.vermont.gov/arcgis/rest/services/Open_Data/OPENDATA_ANR_CADASTRAL_SP_NOCACHE_v2/MapServer', 38, 'MapServer', 'polygon', 5, 'low', 'ANR Open Data Service - Cadastral'),
  ('virginia_conservation_lands__Virginia_Conservation_Lands-0', 'Virginia Conservation Lands', 'State Lands', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Virginia_Conservation_Lands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('major_public_lands_non_dnr__WADNR_PUBLIC_Major_Public_Lands_NonDNR-1', 'Major Public Lands Non DNR', 'Washington', 'state_protected', 'https://gis.dnr.wa.gov/site3/rest/services/Public_Boundaries/WADNR_PUBLIC_Major_Public_Lands_NonDNR/MapServer', 1, 'MapServer', 'polygon', 5, 'low', '<div style=''text-align:Left;''><div><div><p><span>The Non-DNR Major Public Lands (NDMPL) layers contain ownership parcels for Federal, State (excluding WA DNR), County and City lands within the State of Washington. It also includes Tribal administrative boundaries. This data is not connected to WA DNR''s Cadastre layers (these data include WADNR ownership, Public Land Survey System and other cadastral data). As updates are made to Cadastre layers, they may not be reflected in NDMPL.</span></p><p><span>Layers include: Wilderness Areas, Non-DNR Major Public Lands, and Tribal Lands.</span></p></div></div></div>'),
  ('dnr_managed_land_parcels__WADNR_PUBLIC_Cadastre_OpenData-6', 'DNR Managed Land Parcels', 'Washington', 'state_protected', 'https://gis.dnr.wa.gov/site3/rest/services/Public_Boundaries/WADNR_PUBLIC_Cadastre_OpenData/MapServer', 6, 'MapServer', 'polygon', 5, 'low', 'Layers include: WA Survey Points, WA Boundaries, WA Legal Descriptions, WA DNR Regions, WA DNR Districts, WA DNR Units, DNR Managed Land Parcels, Public Land Survey Sections, Public Land Survey Townships, State Outline, State Boundary, and County Boundaries.'),
  ('wisconsin_dnr_managed_land__LF_AGOL_STAGING_WTM_Ext-0', 'Wisconsin - DNR Managed Land', 'State Lands', 'state_protected', 'https://dnrmaps.wi.gov/arcgis/rest/services/LF_DML/LF_AGOL_STAGING_WTM_Ext/MapServer', 0, 'MapServer', 'polygon', 5, 'low', 'Contains:
DNR Mgd Lands by Property - Prop Names Included: Parcels dissovled on Prop Code with Property Names attached, DNR easements on private lands not included.
DNR Mgd Lands by Parcels-No Property NAmes: Contains DNR Mgd Land as parcels, open easements included-- closed easement and inholding are not.'),
  ('state_lands__Wyoming_State_Lands-0', 'State Lands', 'Wyoming', 'state_protected', 'https://services3.arcgis.com/OYP7N6mAJJCyH6hd/arcgis/rest/services/Wyoming_State_Lands/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', NULL),
  ('public_access_areas__PublicAccessAreaBoundaries-0', 'Public Access Areas', 'Wyoming', 'state_protected', 'https://services6.arcgis.com/cWzdqIyxbijuhPLw/arcgis/rest/services/PublicAccessAreaBoundaries/FeatureServer', 0, 'FeatureServer', 'polygon', 5, 'low', 'This data set was developed in order to show Public Access Areas in interactive maps on the public website, produce small scale boundary maps published in GeoPDF and KML form, and for individuals with an interest in Wyoming Game and Fish Department Lands. It is also designed for statewide and regional overview use. Attribute data such as open dates, recreational opportunities, etc. for each area is in the PAA_Locations feature class, which can be joined to this feature class by the PAA_Name field.')
